package com.aistock.market.marketrefs;
import com.aistock.market.support.MarketDatabaseFixture;import com.aistock.common.BusinessException;import java.time.*;import java.sql.Timestamp;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class MarketVersionReferenceMysqlTest {
 @Test void ownershipDemoAndCurrentHeadAreReadOnly(){var j=new MarketDatabaseFixture().jdbc();var now=Instant.parse("2026-10-28T00:00:00Z");j.update("insert into instrument(instrument_id,ticker,display_name,demo_only)values('SH600030','600030','测试',false),('SH600276','600276','测试二',false)");String v=UUID.randomUUID().toString();j.update("insert into market_data_version(version_id,instrument_id,provider,price_basis,status,quality,content_hash,source_payload_hash,fetched_at,published_at,coverage_start,coverage_end)values(?,'SH600030','baostock','RAW','AVAILABLE','ROW_VALIDATED',?,?,?,?,'2026-10-20','2026-10-23')",v,"a".repeat(64),"b".repeat(64),Timestamp.from(now),Timestamp.from(now));var repo=new MarketVersionReferenceRepository(j);assertFalse(repo.meta("SH600030",v,now).currentHead());j.update("insert into instrument_data_head(instrument_id,provider,price_basis,version_id,revision,checked_at) values('SH600030','baostock','RAW',?,1,?)",v,Timestamp.from(now));String before=j.queryForList("select * from instrument_data_head").toString();assertTrue(repo.meta("SH600030",v,now).currentHead());assertThrows(BusinessException.class,()->repo.meta("SH600276",v,now));assertEquals(before,j.queryForList("select * from instrument_data_head").toString());j.update("update instrument set demo_only=true where instrument_id='SH600030'");try{assertThrows(BusinessException.class,()->repo.meta("SH600030",v,now));}finally{j.update("update instrument set demo_only=false where instrument_id='SH600030'");}}
 @Test void aFollowingFixtureCanCleanTheTemporaryDemoRecord(){ownershipDemoAndCurrentHeadAreReadOnly();var next=new MarketDatabaseFixture().jdbc();assertEquals(0,next.queryForObject("select count(*) from instrument where instrument_id='SH600030'",Integer.class));}
}
